@@ -2,6 +2,7 @@ import test from "node:test";
 import assert from "node:assert/strict";
 import { consume, waste } from "../src/domain/batches.js";
 import { onHand } from "../src/domain/items.js";
+import { cook } from "../src/domain/recipes.js";
 import { fresh } from "./helpers.js";

 const at = "2026-10-28T10:00:00Z";
@@ -27,3 +28,30 @@ test("waste is recorded against a batch", () => {
   assert.equal(m.type, "waste");
   assert.equal(store.data.batches.find((b) => b.id === 6).qty, 12);
 });
+
+test("cooking bechamel takes the milk that expires first (FEFO)", () => {
+  const store = fresh();
+  const lot = (id) => store.data.batches.find((b) => b.id === id).lot;
+  // 10 portions need 2 l of milk: exactly lot HD-1022 (expires 2026-10-29).
+  const milk = cook(store, 2, 10, { at }).find((u) => u.itemId === 2);
+  assert.deepEqual(milk.batches.map((u) => [lot(u.batchId), u.qty]), [["HD-1022", 2]]);
+  assert.equal(store.data.batches.find((b) => b.lot === "HD-1026").qty, 8);
+  // The next batch spills over into the newer lot only once the old one is empty.
+  const next = consume(store, 2, 1, { at });
+  assert.deepEqual(next.map((u) => lot(u.batchId)), ["HD-1026"]);
+});
+
+test("consume order: expiry, then no expiry last, then received date, then id", () => {
+  const store = fresh();
+  const batch = (id, expires, receivedOn) => ({ id, itemId: 2, lot: `T-${id}`, qty: 1, receivedOn, expires, location: "fridge" });
+  store.data.batches = [
+    batch(101, null, "2026-10-01"),
+    batch(102, "2026-11-05", "2026-10-20"),
+    batch(103, "2026-11-05", "2026-10-20"),
+    batch(104, "2026-11-05", "2026-10-10"),
+    batch(105, "2026-11-01", "2026-10-25"),
+    { ...batch(106, undefined, "2026-10-01"), expires: undefined },
+  ];
+  const used = consume(store, 2, 6, { at });
+  assert.deepEqual(used.map((u) => u.batchId), [105, 104, 102, 103, 101, 106]);
+});
